import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二十九章 愤怒只会伤害到自己","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/29第二十九章 愤怒只会伤害到自己.md","filePath":"meditation/巴利文大藏经/29第二十九章 愤怒只会伤害到自己.md"}'),_={name:"meditation/巴利文大藏经/29第二十九章 愤怒只会伤害到自己.md"};function r(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第二十九章-愤怒只会伤害到自己" tabindex="-1">第二十九章 愤怒只会伤害到自己 <a class="header-anchor" href="#第二十九章-愤怒只会伤害到自己" aria-label="Permalink to &quot;第二十九章 愤怒只会伤害到自己&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部7相应4经/酸粥经(婆罗门相应/有偈篇/祇夜)</p><p>有一次，佛陀住在王舍城栗鼠饲养处的竹林中，阿修罗王皈依佛陀后，与佛陀和波斯匿王一同进餐，在阿修罗王旁边站立的毗兰耆迦婆罗门横眉怒目、咬牙切齿。他一言不发，默默的独自生着闷气，他心里想：「这个秃头既然哄骗了大王，大王已经皈依他了，我现在也不好去反驳他，真是气死我了，我才赶到这里，不知道他对大王说了什么？如果我早一点来，就不是这个局面了。」</p><p>佛陀看见毗兰耆迦婆罗门愤怒的表情就对他说：“独自愤怒生闷气的人，他们的内心如同被烈火焚烧一样，然而他们对别人生起的愤怒只能伤害到他们自己，因为别人并没有生起愤怒。烈火焚烧生起愤怒的人，却无法焚烧到自己怨恨的人。内心不满、责骂清净没有过错的人，内心生起熊熊怒火的人，他们其实是在折磨和摧残他们自己，他们是在让自己受到煎熬和惩罚，就如同在逆风中抛洒出去的细沙灰尘一样，这些抛洒出去的细沙灰尘会被逆风吹到自己的身上，那些用污言秽语、恶劣行为抹黑别人的人，他们其实是在抹黑他们自己。因为他们的内心生起了这些污言秽语，他们的行为做出了这些恶劣的行径，就如同恶臭难闻的腐烂尸体，尸体本身臭气熏天才可能让旁边的人也沾染上尸体的恶臭味。他们抹黑别人只会让自己臭气熏天，却无法让清净正直的人熏染上恶臭味，因为清净正直的人内心不会生起污言秽语，不会去做这些恶劣的行为。”</p><p>这时，佛陀说偈言：</p><p>「清净无秽恶，以污无垢人。</p><p>恶还其愚人，逆风撒细尘。」</p><p>毗兰耆迦婆罗门听到佛陀对自己的教导，就回答佛陀到：“大德，您说的很有道理，我刚才确实已经被愤怒的烈火焚烧，我刚才确实在想那些辱骂您的污言秽语和对付您的办法，我变成了臭气熏天的尸体，我让自己臭不可闻，我伤害到了自己，却无法伤害到您。请您原谅我，我错了，不该让愤怒奴役和控制我的心智，我在您这里虔诚忏悔，我再也不会无端的指责别人，再也不会无端的生气发怒了，请您让我皈依您，让我做您的在家修行弟子吧，我愿意按您的正法去修行。”</p><p>佛陀接受了毗兰耆迦婆罗门的皈依。毗兰耆迦皈依佛陀后，佛陀就让他坐在自己的旁边一同用餐。</p>',10)]))}const f=e(_,[["render",r]]);export{m as __pageData,f as default};
